// Group Shifted Strings: "abc", "bcd", "xyz" → ключ "abc"
static string ShiftKey(string s) {
    var key = new char[s.Length];
    for (int i = 0; i < s.Length; i++)
        key[i] = (char)('a' + (s[i] - s[0] + 26) % 26);   // сдвиг к первой букве 'a'
    return new string(key);
}

