bool HasCycle(int v, List<int>[] next, int[] state) {
    state[v] = 1;
    foreach (int d in next[v]) {
        if (state[d] == 1) return true;                    // вернулись на свой же путь
        if (state[d] == 0 && HasCycle(d, next, state)) return true;
    }
    state[v] = 2;                                          // из v цикла нет — больше не заходим
    return false;
}
