public Node CloneGraph(Node node) {
    if (node == null) return null;
    var copy = new Dictionary<Node, Node> { [node] = new Node(node.val) };
    var queue = new Queue<Node>();
    queue.Enqueue(node);
    while (queue.Count > 0) {
        var cur = queue.Dequeue();
        foreach (var nb in cur.neighbors) {
            if (!copy.ContainsKey(nb)) {           // первая встреча: создать копию и запланировать
                copy[nb] = new Node(nb.val);
                queue.Enqueue(nb);
            }
            copy[cur].neighbors.Add(copy[nb]);    // ребро копии — к копии соседа
        }
    }
    return copy[node];
}

readonly Dictionary<Node, Node> copy = new Dictionary<Node, Node>();

public Node Clone(Node node) {
    if (node == null) return null;
    if (copy.TryGetValue(node, out var done)) return done;
    var c = new Node(node.val);
    foreach (var nb in node.neighbors)
        c.neighbors.Add(Clone(nb));
    copy[node] = c;
    return c;
}

