public int SlidingPuzzle(int[][] board) {
    // клетки 2×3: 0 1 2 / 3 4 5; moves[i] — куда может уйти пустая клетка из i
    int[][] moves = { new[] { 1, 3 }, new[] { 0, 2, 4 }, new[] { 1, 5 },
                      new[] { 0, 4 }, new[] { 1, 3, 5 }, new[] { 2, 4 } };
    string start = string.Concat(board[0]) + string.Concat(board[1]), goal = "123450";
    var seen = new HashSet<string> { start };
    var queue = new Queue<string>();
    queue.Enqueue(start);
    for (int steps = 0; queue.Count > 0; steps++)
        for (int size = queue.Count; size > 0; size--) {
            string s = queue.Dequeue();
            if (s == goal) return steps;
            int z = s.IndexOf('0');
            foreach (int m in moves[z]) {
                var a = s.ToCharArray();
                (a[z], a[m]) = (a[m], a[z]);          // сдвинуть плитку в пустую клетку
                var t = new string(a);
                if (seen.Add(t)) queue.Enqueue(t);
            }
        }
    return -1;
}

public int LadderLength(string begin, string end, IList<string> wordList) {
    var words = new HashSet<string>(wordList);
    if (!words.Contains(end)) return 0;
    var front = new HashSet<string> { begin };
    var back = new HashSet<string> { end };
    words.Remove(begin); words.Remove(end);
    for (int length = 2; front.Count > 0 && back.Count > 0; length++) {
        if (front.Count > back.Count) (front, back) = (back, front);   // растим меньший фронт
        var next = new HashSet<string>();
        foreach (var w in front) {
            var a = w.ToCharArray();
            for (int i = 0; i < a.Length; i++) {
                char orig = a[i];
                for (char ch = 'a'; ch <= 'z'; ch++) {
                    a[i] = ch;
                    var t = new string(a);
                    if (back.Contains(t)) return length;        // фронты встретились
                    if (words.Remove(t)) next.Add(t);
                }
                a[i] = orig;
            }
        }
        front = next;
    }
    return 0;
}

