    int Find(int x) {
        while (parent[x] != x) x = parent[x] = parent[parent[x]];
        return x;
    }
    int count = n;
    foreach (var e in edges) {
        int a = Find(e[0]), b = Find(e[1]);
        parent[a] = b;
        count--;
    }
    return count;
}

