    dist[k] = 0;
    var pq = new PriorityQueue<int, int>();      // .NET 6+: узел по расстоянию
    pq.Enqueue(k, 0);
    while (pq.TryDequeue(out int u, out int d)) {
        if (d > dist[u]) continue;               // устаревшая запись
        foreach (var (v, w) in adj[u])
            if (d + w < dist[v]) {
                dist[v] = d + w;
                pq.Enqueue(v, dist[v]);          // decrease-key нет: кладём ещё раз
            }
    }
    int max = 0;
    for (int v = 1; v <= n; v++) {
        if (dist[v] == int.MaxValue) return -1;  // сигнал дошёл не до всех
        max = Math.Max(max, dist[v]);
    }
    return max;
}

