public int FindCheapestPrice(int n, int[][] flights, int src, int dst, int k) {
    var cost = new int[n];
    Array.Fill(cost, int.MaxValue);
    cost[src] = 0;
    for (int round = 0; round <= k; round++) {           // проход i: пути из ≤ i + 1 рейсов
        var next = (int[])cost.Clone();                  // читаем прошлый проход, пишем в копию
        foreach (var f in flights)
            if (cost[f[0]] != int.MaxValue && cost[f[0]] + f[2] < next[f[1]])
                next[f[1]] = cost[f[0]] + f[2];
        cost = next;
    }
    return cost[dst] == int.MaxValue ? -1 : cost[dst];
}

// сколько стен минимум сломать на пути s → t: войти в пустую клетку — 0, в стену — 1
int MinWalls(bool[] wall, int w, int h, int s, int t) {
    var dist = new int[w * h];
    Array.Fill(dist, int.MaxValue);
    dist[s] = 0;
    var deque = new LinkedList<int>();
    deque.AddFirst(s);
    while (deque.Count > 0) {
        int u = deque.First.Value;
        deque.RemoveFirst();
        int x = u % w;
        for (int k = 0; k < 4; k++) {
            int v = k == 0 ? (x > 0 ? u - 1 : -1) : k == 1 ? (x < w - 1 ? u + 1 : -1) : k == 2 ? u - w : u + w;
            if (v < 0 || v >= w * h) continue;
            int c = wall[v] ? 1 : 0;
            if (dist[u] + c >= dist[v]) continue;
            dist[v] = dist[u] + c;
            if (c == 0) deque.AddFirst(v); else deque.AddLast(v);   // 0 — в начало, 1 — в конец
        }
    }
    return dist[t];
}

