    for (int i = 0; i <= a.Length; i++) dp[i, 0] = i;   // удалить всё
    for (int j = 0; j <= b.Length; j++) dp[0, j] = j;   // вставить всё
    for (int i = 1; i <= a.Length; i++)
        for (int j = 1; j <= b.Length; j++)
            dp[i, j] = a[i - 1] == b[j - 1]
                ? dp[i - 1, j - 1]
                : 1 + Math.Min(dp[i - 1, j - 1], Math.Min(dp[i - 1, j], dp[i, j - 1]));
