public bool CanPartition(int[] nums) {
    int total = nums.Sum();
    if (total % 2 != 0) return false;
    int half = total / 2;
    var ok = new bool[half + 1];
    ok[0] = true;
    foreach (int x in nums)
        for (int s = x; s <= half; s++)
            ok[s] |= ok[s - x];
    return ok[half];
}

