public sealed class History<T> {          // последние cap значений, старые затираются
    readonly T[] buf;
    readonly uint mask;
    uint tail;                              // всего записано; не заворачивается

    public History(int capPow2) { buf = new T[capPow2]; mask = (uint)capPow2 - 1; }

    public int Count => (int)Math.Min(tail, (uint)buf.Length);

    public void Push(T value) => buf[tail++ & mask] = value;

    public T Ago(int i) => buf[(tail - 1 - (uint)i) & mask];   // 0 — последнее, i < Count
}

pool = new ObjectPool<Bullet>(
    createFunc: () => Instantiate(prefab),
    actionOnGet: b => { b.gameObject.SetActive(true); b.inPool = false; },
    actionOnRelease: b => b.gameObject.SetActive(false),
    actionOnDestroy: b => Destroy(b.gameObject),
    collectionCheck: true,                 // ловит двойной Release, но только в редакторе
    defaultCapacity: 64, maxSize: 512);

public void Despawn(Bullet b) {
    if (b.inPool) return;                  // уже в пуле: второй вызов (таймер после попадания) — мимо
    b.inPool = true;
    pool.Release(b);
}

public int Get(int key) {
    if (!map.TryGetValue(key, out var node)) return -1;
    order.Remove(node);
    order.AddLast(node);
    return node.Value.val;
}

public void Put(int key, int value) {
    if (map.TryGetValue(key, out var node)) order.Remove(node);
    else if (map.Count == capacity) {
        map.Remove(order.Last.Value.key);
        order.RemoveLast();
    }
    map[key] = order.AddFirst((key, value));
}
